function workshopCredits({ credits }) {
    let best = 0;
    for (let mask = 0; mask < 2 ** credits.length; mask++) {
        if ((mask & (mask << 1)) !== 0)
            continue;
        let total = 0;
        for (let j = 0; j < credits.length; j++)
            if ((mask & (1 << j)) !== 0)
                total += credits[j];
        best = Math.max(best, total);
    }
    return best;
}

function workshopCredits({ credits }) {
    let twoBack = 0, oneBack = 0;
    for (const credit of credits) {
        const current = Math.max(oneBack, twoBack + credit);
        twoBack = oneBack;
        oneBack = current;
    }
    return oneBack;
}
